const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const engineerId = String(payload.engineerId || payload.id || `ENG-${Math.floor(1000 + Math.random() * 9000)}`).trim();
const fullName = String(payload.fullName || payload.name || 'New Engineer').trim();
const personalEmail = String(payload.email || payload.personalEmail || '').trim().toLowerCase();
const role = String(payload.role || 'Full-Stack Software Engineer').trim();
const department = String(payload.department || 'Platform Engineering').trim();
const startDate = String(payload.startDate || new Date().toISOString().split('T')[0]).trim();
const managerName = String(payload.managerName || 'Vikash Saravanan (Lead System Engineer)').trim();
const githubUsername = String(payload.githubUsername || payload.github || '').trim();

const cleanName = fullName.toLowerCase().replace(/[^a-z0-9]/g, '.');
const corporateEmail = `${cleanName}@logicintelligence.com`;

const accessChecklist = [
  { item: 'GitHub Organization Invite (logic-intelligence-technologies)', status: 'PROVISIONED', team: 'core-platform' },
  { item: 'Supabase Development Workspace Role', status: 'PROVISIONED', role: 'developer' },
  { item: '1Password Team Vault Access', status: 'INVITED', vault: 'Engineering-Shared' },
  { item: 'Zero-Trust Cloudflare Gateway Access', status: 'PENDING_ENROLLMENT' },
  { item: 'Sentry / Datadog Telemetry Read Access', status: 'PROVISIONED' }
];

const complianceChecklist = [
  { requirement: 'GPG & SSH commit signing key configured', completed: false, mandatory: true },
  { requirement: 'Hardware 2FA / WebAuthn token enrolled', completed: false, mandatory: true },
  { requirement: 'Zero-Trust Non-PHI security policy signed', completed: false, mandatory: true },
  { requirement: 'LIT strict code review and CI verification training', completed: false, mandatory: true }
];

const devEnvironmentSpec = {
  nodeVersion: '>=20.0.0',
  pythonVersion: '>=3.12.0',
  dockerRequired: true,
  recommendedIDE: 'VS Code with Antigravity Customizations',
  repoCloneCommand: 'git clone git@github.com:logic-intelligence-technologies/platform.git'
};

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    engineer: {
      engineerId,
      fullName,
      personalEmail,
      corporateEmail,
      role,
      department,
      startDate,
      managerName,
      githubUsername,
      accessChecklist,
      complianceChecklist,
      devEnvironmentSpec
    }
  }
}];

const item = $input.first().json;
const eng = item.engineer;

const welcomePackage = {
  recipientName: eng.fullName,
  corporateEmail: eng.corporateEmail,
  personalEmail: eng.personalEmail,
  role: eng.role,
  manager: eng.managerName,
  startDate: eng.startDate,
  portalPath: `/internal/onboarding/welcome/${eng.engineerId}`,
  firstDaySchedule: [
    { time: '10:00 AM IST', title: 'Welcome & Workspace Setup with Vikash Saravanan' },
    { time: '11:30 AM IST', title: 'Security Credentials, GPG Keys & 1Password Vault Walkthrough' },
    { time: '02:00 PM IST', title: 'System Architecture & Multi-Agent Orchestration Deep Dive' },
    { time: '04:00 PM IST', title: 'First PR Submission & CI/CD Pipeline Verification' }
  ],
  accessChecklist: eng.accessChecklist,
  complianceChecklist: eng.complianceChecklist,
  devSpec: eng.devEnvironmentSpec,
  supportChannel: '#engineering-onboarding'
};

return [{
  json: {
    eventId: item.eventId,
    status: 'ops.engineer_onboarded',
    detail: {
      engineerId: eng.engineerId,
      fullName: eng.fullName,
      corporateEmail: eng.corporateEmail,
      welcomePackage,
      provisionedAt: new Date().toISOString()
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'ops.engineer_onboarded',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
